#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int maxLength(const string& s) {
    string tempStr = "";
    bool insideParentheses = false;
    for (size_t i = 0; i < s.length(); i++) {
        char ch = s[i];
        if (ch == '(')
            insideParentheses = true;
        else if (ch == ')') {
            insideParentheses = false;
            tempStr += "_";
        }
        if (!insideParentheses && ch != ')')
            tempStr += ch;
    }
    size_t maxLen = 0;
    size_t start = 0;
    for (size_t i = 0; i <= tempStr.length(); i++) {
        if (i == tempStr.length() || tempStr[i] == '_') {
            size_t length = i - start;
            maxLen = max(maxLen, length);
            start = i + 1;
        }
    }
    return static_cast<int>(maxLen);
}

int count(const string& s) {
    int cnt = 0;
    size_t start = 0;
    for (size_t i = 0; i <= s.length(); i++) {
        if (i == s.length() || s[i] == '_') {
            if (i - start > 0)
                cnt++;
            start = i + 1;
        }
    }
    return cnt;
}

int words(const string& s) {
    int total = 0;
    string current = "";
    bool inParent = false;
    for (size_t i = 0; i < s.length(); i++) {
        char c = s[i];
        if (c == '(')
            inParent = true;
        else if (c == ')') {
            inParent = false;
            total += count(current);
            current.clear();
        } else if (inParent && c != '(') {
            current += c;
        }
    }
    return total;
}

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;
    cout << maxLength(s) << " " << words(s) << endl;
    return 0;
}
